import clsx from 'clsx';
import React, { FocusEvent, forwardRef, useMemo } from 'react';
import { isElement } from 'react-is';

import { RadioGroupContext } from './contexts/RadioGroupContext.js';
import { Radio } from './Radio.js';
import { radioGroupCSS } from './RadioGroup.sty.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import { _useFormControlState } from '../../core/hooks/useFormControlState.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { useRovingFocus } from '../../core/hooks/useRovingFocus.js';
import { _useSharedInputPropsContext } from '../../core/hooks/useSharedInputPropsContext.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { FormControlStateProps } from '../../core/types/form-control-state.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Hint } from '../forms-core/components/hint/Hint.js';

//#region Typings
/** Props of the RadioGroup component. */
export interface RadioGroupBaseProps
  extends WithChildren,
    FormControlStateProps,
    AriaLabelingProps,
    DOMProps,
    StylingProps,
    DataTestId {
  /**
   * A radio group is defined by giving each of the radio buttons in the group the same name.
   * This must be unique for each group and is also used when submitting it in a form.
   */
  name?: string;
  /**
   * Whether the whole group is disabled.
   * @defaultValue false
   */
  disabled?: boolean;
}

export interface RadioGroupControlledProps {
  /** The default value of the radio group (uncontrolled). */
  defaultValue?: never;
  /** The value of the radio group (controlled). */
  value: string;
  /** Handler that is called when the value of the group changes. */
  onChange: (value: string, event?: FocusEvent<HTMLInputElement>) => void;
}

export interface RadioGroupUncontrolledProps {
  /** The default value of the radio group (uncontrolled). */
  defaultValue?: string;
  /** The value of the radio group (controlled). */
  value?: never;
  /** Handler that is called when the value of the group changes. */
  onChange?: never;
}

export type RadioGroupProps = RadioGroupBaseProps &
  (RadioGroupControlledProps | RadioGroupUncontrolledProps);
//#endregion

/**
 * Radio buttons allow users to select one option from
 * a group of related options. To group options, wrap the
 * `Radio` components inside a 'RadioGroup' component.
 */
export const RadioGroup = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  RadioGroupProps
>((props, forwardedRef) => {
  const {
    children,
    id: propId,
    disabled: propDisabled,
    name,
    value,
    defaultValue,
    controlState,
    onChange,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...restProps
  }: RadioGroupProps = props;

  const {
    id,
    disabled: isDisabled = false,
    labelId,
  } = _useSharedInputPropsContext({
    disabled: propDisabled,
    id: propId,
  });

  const hintId = `errorhint-${id}`;

  const [hasError, hint] = _useFormControlState(controlState);

  const [selectedValue, setSelectedValue] = _useControllableState({
    defaultValue,
    value,
  });

  const radioItems = useMemo(
    () => React.Children.toArray(children),
    [children],
  );

  const initialIndex = useMemo(
    () =>
      radioItems.findIndex(
        (child) =>
          isElement(child) &&
          child.type === Radio &&
          child.props.value === selectedValue,
      ),
    // we only need to set the initial index on the first render to prevent re-renders due to the roving focus
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  const { containerRef } = useRovingFocus<HTMLDivElement, HTMLInputElement>({
    initialIndex: initialIndex !== -1 ? initialIndex : undefined,
    direction: 'both',
    focusableChildrenSelector: 'input[type="radio"]',
  });

  const rootRef = useMergeRefs([containerRef, forwardedRef]);

  return (
    <div
      data-testid={dataTestId}
      aria-orientation="vertical"
      role="radiogroup"
      aria-live="polite"
      aria-invalid={hasError}
      aria-disabled={isDisabled}
      aria-describedby={`${labelId ?? ''} ${hasError ? hintId : ''}`}
      ref={rootRef}
      className={clsx(consumerClassName, radioGroupCSS)}
      style={consumerStyle}
      {...restProps}
    >
      <RadioGroupContext.Provider
        value={{
          name,
          isDisabled,
          hasError,
          selectedValue,
          setSelectedValue,
          onChange,
        }}
      >
        <Flex flexDirection="column" gap={8}>
          {children}
        </Flex>
      </RadioGroupContext.Provider>
      <Hint hasError={hasError} disabled={isDisabled} id={hintId}>
        {hint}
      </Hint>
    </div>
  );
});

(RadioGroup as typeof RadioGroup & { displayName: string }).displayName =
  'RadioGroup';
